def evaluate_alert(page_outcomes):
    if not page_outcomes:
        return "insufficient data"
    actionable_count = sum(1 for p in page_outcomes if p["action_taken"])
    rate = (actionable_count / len(page_outcomes)) * 100
    if rate >= 50:
        return "keep"
    elif rate >= 20:
        return "retune"
    else:
        return "delete"

print(evaluate_alert(page_outcomes))  # 1 out of 5 actionable = 20% -> 'retune'

def check_rotation_health(weeks_between_oncall, recent_pages_per_shift):
    reasons = []
    if weeks_between_oncall < 3:
        reasons.append(
            f"Too frequent: only {weeks_between_oncall} weeks since last on-call shift (minimum: 3)"
        )
    recent = recent_pages_per_shift[-4:]
    if recent:
        avg_pages = sum(recent) / len(recent)
        if avg_pages > 8:
            reasons.append(
                f"Too high volume: average {avg_pages:.1f} pages/shift over last {len(recent)} shifts (max: 8)"
            )
    return reasons

print(check_rotation_health(2, [10, 9, 7, 12]))
# ["Too frequent: only 2 weeks since last on-call shift (minimum: 3)",
#  "Too high volume: average 9.5 pages/shift over last 4 shifts (max: 8)"]
